def load_embedded_programs():
    """把 Atlas 2.0 和 Atlas 3.0 原始代码分别加载到独立命名空间。"""
    atlas2_namespace = {
        "__name__": "atlas2_embedded",
        "__file__": str(Path(__file__).resolve())
    }
    atlas3_namespace = {
        "__name__": "atlas3_embedded",
        "__file__": str(Path(__file__).resolve())
    }

    exec(ATLAS2_SOURCE, atlas2_namespace)
    exec(ATLAS3_SOURCE, atlas3_namespace)

    return atlas2_namespace, atlas3_namespace


def show_combined_intro():
    print("\n========================================")
    print("Atlas 2.0 + Atlas 3.0 Full Combined")
    print("完整合并入口程序")
    print("========================================")
    print("1. Atlas 2.0：Project Database + Daily Task + Bug Manager + Weekly Report")
    print("2. Atlas 3.0：Profile + Skills + History + Learning Planner + Emotion Memory + Mentor Recommendation")
    print("========================================")
    print(f"当前文件夹：{BASE_DIR}")
    print("========================================")


def main():
    atlas2_namespace, atlas3_namespace = load_embedded_programs()

    while True:
        show_combined_intro()
        print("请选择要运行的程序：")
        print("1. 进入 Atlas 2.0 完整程序")
        print("2. 进入 Atlas 3.0 完整程序")
        print("3. 查看说明")
        print("4. 退出")

        choice = input("请输入数字 1-4：").strip()

        if choice == "1":
            print("\n正在进入 Atlas 2.0 完整程序...")
            atlas2_namespace["main"]()

        elif choice == "2":
            print("\n正在进入 Atlas 3.0 完整程序...")
            atlas3_namespace["main"]()

        elif choice == "3":
            print("\n说明：")
            print("这个文件已经把 atlas2_main(1).py 和 atlas3_main.py 合并进同一个 Python 文件。")
            print("为了避免两个原程序里同名函数互相覆盖，我把它们放进两个独立命名空间。")
            print("这样可以最大程度保留两个程序的完整功能。")
            print("Atlas 2.0 会继续使用 atlas2_data.json。")
            print("Atlas 3.0 会继续使用 atlas3_data.json。")
            print("project_log.txt 会继续记录运行过程。")

        elif choice == "4":
            print("\n已退出 Atlas 2.0 + Atlas 3.0 Full Combined Program。")
            break

        else:
            print("输入无效，请输入 1 到 4。")


if __name__ == "__main__":
    main()
